/*
 * BL616 MOD->PCM->HDMI. The Apple IIgs DOC and its sound RAM are uninvolved.
 * Audio is generated by public-domain HxCMOD at exactly HDMI's 44,100 Hz.
 * SPI XFER SPACE 6 writes one 16-bit LE left/right pair per 4 bytes.
 *
 * IMPORTANT: the original NTP player is intentionally NOT included.
 * No 6502 mailbox, native DOC register writes, DOC oscillator patches,
 * sound sample-bank generation, or NTP instrument translation.
 */
#include "mcu_mod_audio.h"
#include "third_party/hxcmod/hxcmod.h"
#include "fpga_spi.h"
#include "disk.h"
#include "osd_console.h"
#include "FreeRTOS.h"
#include "task.h"
#include "usb_osal.h"
#include <ctype.h>
#include <string.h>

#define PCM_SPACE 6u
#define PCM_CTRL_RESET 0x800000u
#define PCM_CTRL_ENABLE 0x800001u
#define PCM_STATUS 0x800000u
#define PCM_BLOCK_FRAMES 256u
#define PCM_BLOCK_BYTES (PCM_BLOCK_FRAMES*4u)
#define MOD_FILE_LIMIT 196608u
#define PCM_HZ 44100u
#define MOD_PATH_CAP 128u

static modcontext s_ctx;
static msample s_pcm[PCM_BLOCK_FRAMES*2u];
static uint8_t s_status[16];
static uint8_t *s_file;
static volatile uint32_t s_path_seq;
static uint32_t s_seen_seq;
static char s_path[MOD_PATH_CAP];
static volatile uint32_t s_stop;
static volatile uint32_t s_replay;
static char s_last_request[MOD_PATH_CAP]; // written by modpcm task alone
static volatile uint32_t s_has_last;      // published after full path copy
static volatile mod_pcm_status_t s_state=MOD_PCM_IDLE;

static bool valid_path(const char *path)
{
    if(!path)return false;
    size_t n=strlen(path);
    if(n<5u || n>=MOD_PATH_CAP || strstr(path,"..") ||
       path[0]=='/' || strchr(path,':') || strchr(path,'\\'))return false;
    return path[n-4]=='.' &&
           tolower((unsigned char)path[n-3])=='m' &&
           tolower((unsigned char)path[n-2])=='o' &&
           tolower((unsigned char)path[n-1])=='d';
}
bool mod_audio_choose(const char *path)
{
    if(!valid_path(path))return false;
    __atomic_add_fetch(&s_path_seq,1u,__ATOMIC_RELEASE);
    memset(s_path,0,sizeof s_path);
    memcpy(s_path,path,strlen(path)+1u);
    __atomic_add_fetch(&s_path_seq,1u,__ATOMIC_RELEASE);
    s_state=MOD_PCM_SELECTED;
    return true;
}
static bool take_pending(char out[MOD_PATH_CAP])
{
    uint32_t a=__atomic_load_n(&s_path_seq,__ATOMIC_ACQUIRE);
    if(!a || (a&1u) || a==s_seen_seq)return false;
    memcpy(out,s_path,MOD_PATH_CAP);
    uint32_t b=__atomic_load_n(&s_path_seq,__ATOMIC_ACQUIRE);
    if(a!=b || (b&1u))return false;
    s_seen_seq=b;
    return true;
}
mod_pcm_status_t mod_audio_status(void){return s_state;}
void mod_audio_request_stop(void)
{
    __atomic_store_n(&s_stop,1u,__ATOMIC_RELEASE);
}
bool mod_audio_replay_last(void)
{
    if(!__atomic_load_n(&s_has_last,__ATOMIC_ACQUIRE))
        return false;
    __atomic_store_n(&s_replay,1u,__ATOMIC_RELEASE);
    return true;
}
static bool pcm_read_status(void)
{
    fpga_spi_xfer_read(PCM_SPACE,PCM_STATUS,s_status,sizeof s_status);
    return s_status[0]==0x50 && s_status[1]==0x43 &&
           s_status[2]==1u;
}
static uint16_t pcm_free(void)
{
    return (uint16_t)s_status[6] | (uint16_t)((uint16_t)s_status[7]<<8);
}
static uint16_t pcm_underruns(void)
{
    return (uint16_t)s_status[8] | (uint16_t)((uint16_t)s_status[9]<<8);
}
static void pcm_control(uint32_t address,uint8_t value)
{
    fpga_spi_xfer_write(PCM_SPACE,address,&value,1u);
}
static void player_release(void)
{
    pcm_control(PCM_CTRL_ENABLE,0);
    pcm_control(PCM_CTRL_RESET,0xA5u);
    hxcmod_unload(&s_ctx);
    if(s_file)vPortFree(s_file);
    s_file=NULL;
}
static bool player_load(const char *path)
{
    fs_req_t fs;
    uint32_t rem,off;
    bool ok=false,opened=false;
    memset(&fs,0,sizeof fs);
    fs.op=FSOP_MOD_OPEN;fs.path=path;
    if(disk_fs_request(&fs)!=0)goto finish;
    opened=true;
    if(fs.size<1084u || fs.size>MOD_FILE_LIMIT) {
        osd_log("MCU MOD: UNSUPPORTED SIZE %lu (MAX 192K)",
                (unsigned long)fs.size);
        goto finish;
    }
    s_file=(uint8_t*)pvPortMalloc(fs.size);
    if(!s_file) {
        osd_log("MCU MOD: NO RAM FOR %lu BYTE FILE",(unsigned long)fs.size);
        goto finish;
    }
    rem=fs.size;off=0;
    while(rem) {
        memset(&fs,0,sizeof fs);
        fs.op=FSOP_MOD_READ;
        fs.buf=s_file+off;
        fs.len=rem>4096u?4096u:rem;
        if(disk_fs_request(&fs)!=0 || fs.out==0 || fs.out>fs.len)
            goto finish;
        rem-=fs.out;off+=fs.out;
    }
    if(!hxcmod_init(&s_ctx) ||
       !hxcmod_setcfg(&s_ctx,PCM_HZ,100,1) ||
       !hxcmod_load(&s_ctx,s_file,(int)off)) {
        osd_log("MCU MOD: HxCMOD REJECTED FILE");
        goto finish;
    }
    osd_log("MCU MOD: HxCMOD %luB 44100 STEREO",
            (unsigned long)off);
    ok=true;
finish:
    if(opened){
        memset(&fs,0,sizeof fs);
        fs.op=FSOP_MOD_CLOSE;
        (void)disk_fs_request(&fs);
    }
    if(!ok) {
        hxcmod_unload(&s_ctx);
        if(s_file)vPortFree(s_file);
        s_file=NULL;
    }
    return ok;
}
static void pcm_send_block(void)
{
    // HxCMOD native signed 16-bit stereo interleaved.
    // RV32 BL616 is little endian: Llo,Lhi,Rlo,Rhi per stereo frame.
    hxcmod_fillbuffer(&s_ctx,s_pcm,PCM_BLOCK_FRAMES,NULL);
    fpga_spi_xfer_write(PCM_SPACE,0,(const uint8_t*)s_pcm,PCM_BLOCK_BYTES);
}
void mod_audio_task(void *arg)
{
    char requested[MOD_PATH_CAP];
    bool playing=false;
    uint32_t blocks=0,window=0;
    (void)arg;
    s_file=NULL;
    s_state=MOD_PCM_IDLE;
    osd_log("MCU MOD: DIRECT HxCMOD->HDMI READY");
    for(;;) {
        const bool selected=take_pending(requested);
        const bool replay=__atomic_exchange_n(&s_replay,0u,__ATOMIC_ACQ_REL)!=0u;
        if(selected || (replay && __atomic_load_n(&s_has_last,__ATOMIC_ACQUIRE))) {
            if(selected){
                // A mailbox replay copies only from this task's own cached
                // validated path, avoiding concurrent menu string writes.
                memcpy(s_last_request,requested,sizeof(s_last_request));
                __atomic_store_n(&s_has_last,1u,__ATOMIC_RELEASE);
            }else{
                memcpy(requested,s_last_request,sizeof(requested));
            }
            if(playing) {
                player_release();
                playing=false;
            }
            s_state=MOD_PCM_LOADING;
            if(!pcm_read_status()){
                osd_log("MCU MOD: NEED DIRECT PCM FPGA (SPACE6 PC V1)");
                s_state=MOD_PCM_ERROR;
            }else if(player_load(requested)) {
                pcm_control(PCM_CTRL_RESET,0xA5u);
                pcm_control(PCM_CTRL_ENABLE,1u);
                blocks=window=0;
                playing=true;
                s_state=MOD_PCM_PLAYING;
            } else {
                s_state=MOD_PCM_ERROR;
            }
        }
        if(__atomic_exchange_n(&s_stop,0u,__ATOMIC_ACQ_REL)) {
            if(playing){
                player_release();playing=false;
            }
            s_state=MOD_PCM_STOPPED;
            osd_log("MCU MOD: PCM STOPPED");
        }
        if(playing) {
            if(!pcm_read_status()) {
                osd_log("MCU MOD: FPGA PCM LINK LOST");
                player_release();playing=false;
                s_state=MOD_PCM_ERROR;
            } else if(pcm_free()>=PCM_BLOCK_FRAMES) {
                pcm_send_block();
                ++blocks;
                // All counters come from FPGA's actual HDMI-clocked FIFO.
                if(++window>=384u) {
                    osd_log("MCU MOD: FRAMES=%lu FREE=%u UDR=%u",
                            (unsigned long)(blocks*PCM_BLOCK_FRAMES),
                            (unsigned)pcm_free(),
                            (unsigned)pcm_underruns());
                    window=0;
                }
            }
        }
        vTaskDelay(pdMS_TO_TICKS(2));
    }
}
